"""Original 256px ivory/cavity albedo, normal and ORM atlases for two authored skull LODs."""
import bpy,pathlib,json,struct,zlib,base64,hashlib
root=pathlib.Path.cwd();out=root/'.art/skull-baked';out.mkdir(parents=True,exist_ok=True)
bpy.ops.wm.open_mainfile(filepath=str(root/'.art/skull-authored/skull-editable-authoring.blend'))
scene=bpy.context.scene;scene.render.engine='CYCLES';scene.cycles.device='CPU';scene.cycles.samples=32;scene.cycles.use_denoising=False;scene.render.bake.margin=3;scene.render.bake.use_clear=False;scene.render.bake.use_selected_to_active=False
N=256;encoded={};stats={}
def byte(v):return max(0,min(255,round(v*255)))
def srgb(v):return 12.92*v if v<=.0031308 else 1.055*max(v,0)**(1/2.4)-.055
def png(path,data):
 def c(k,p):return struct.pack('>I',len(p))+k+p+struct.pack('>I',zlib.crc32(k+p)&0xffffffff)
 rows=b''.join(b'\0'+data[y*N*4:(y+1)*N*4] for y in range(N));path.write_bytes(b'\x89PNG\r\n\x1a\n'+c(b'IHDR',struct.pack('>IIBBBBB',N,N,8,6,0,0,0))+c(b'IDAT',zlib.compress(rows,9))+c(b'IEND',b''))
for lod in ['mob','boss']:
 body=bpy.data.objects['Runtime_Skull_'+lod]
 for ob in bpy.context.scene.objects:ob.hide_render=ob!=body;ob.select_set(False)
 body.hide_set(False);body.hide_render=False;body.select_set(True);bpy.context.view_layer.objects.active=body
 zones=[p.material_index for p in body.data.polygons]
 body.data.materials.clear();materials=[]
 for cavity in [False,True]:
  mat=bpy.data.materials.new('Authored ivory '+lod+(' cavities' if cavity else ' cortex'));mat.use_nodes=True;mat.use_fake_user=True;body.data.materials.append(mat)
  ns=mat.node_tree.nodes;ns.clear();lk=mat.node_tree.links
  output=ns.new('ShaderNodeOutputMaterial');bsdf=ns.new('ShaderNodeBsdfPrincipled');lk.new(bsdf.outputs[0],output.inputs['Surface'])
  coords=ns.new('ShaderNodeTexCoord');noise=ns.new('ShaderNodeTexNoise');noise.inputs['Scale'].default_value=8;noise.inputs['Detail'].default_value=3;noise.inputs['Roughness'].default_value=.65;lk.new(coords.outputs['Generated'],noise.inputs['Vector'])
  color=ns.new('ShaderNodeValToRGB');r=color.color_ramp
  r.elements[0].position=.2;r.elements[0].color=(.40,.30,.175,1)
  r.elements[1].position=.8;r.elements[1].color=(.83,.74,.55,1)
  lk.new(noise.outputs['Fac'],color.inputs['Fac']);lk.new(color.outputs['Color'],bsdf.inputs['Base Color'])
  rough=ns.new('ShaderNodeMapRange');rough.inputs['To Min'].default_value=.48;rough.inputs['To Max'].default_value=.72;lk.new(noise.outputs['Fac'],rough.inputs['Value']);lk.new(rough.outputs['Result'],bsdf.inputs['Roughness'])
  fine=ns.new('ShaderNodeTexNoise');fine.inputs['Scale'].default_value=65;fine.inputs['Detail'].default_value=2;lk.new(coords.outputs['Generated'],fine.inputs['Vector'])
  bump=ns.new('ShaderNodeBump');bump.inputs['Strength'].default_value=.12;bump.inputs['Distance'].default_value=.0014;lk.new(fine.outputs['Fac'],bump.inputs['Height']);lk.new(bump.outputs['Normal'],bsdf.inputs['Normal'])
  emission=ns.new('ShaderNodeEmission');target=ns.new('ShaderNodeTexImage');ns.active=target
  materials.append((mat,output,bsdf,color,rough,emission,target))
 for polygon,zone in zip(body.data.polygons,zones):polygon.material_index=zone
 def bake(name,kind,base,socket=None):
  im=bpy.data.images.new(lod+'-'+name,width=N,height=N,alpha=True,float_buffer=True);im.colorspace_settings.name='Non-Color';im.pixels=list(base)*(N*N)
  for mat,output,bsdf,color,rough,emission,target in materials:
   target.image=im;mat.node_tree.nodes.active=target;lk=mat.node_tree.links
   if socket:
    lk.new((color.outputs['Color'] if socket=='color' else rough.outputs['Result']),emission.inputs['Color']);lk.new(emission.outputs[0],output.inputs['Surface'])
   else:lk.new(bsdf.outputs[0],output.inputs['Surface'])
  bpy.ops.object.bake(type=kind);im.pack();return list(im.pixels)
 p=bake('ivory-color','EMIT',(.6,.5,.32,1),'color');r=bake('roughness','EMIT',(.6,.6,.6,1),'rough');n=bake('normal','NORMAL',(.5,.5,1,1));a=bake('occlusion','AO',(1,1,1,1))
 rgba={k:bytearray(N*N*4) for k in ['color','normal','orm']}
 for i in range(N*N):
  q=i*4
  for c in range(3):rgba['color'][q+c]=byte(srgb(p[q+c]));rgba['normal'][q+c]=byte(n[q+c])
  rgba['orm'][q]=byte(.65+.35*a[q]);rgba['orm'][q+1]=byte(r[q]);rgba['orm'][q+2]=0
  for value in rgba.values():value[q+3]=255
 encoded[lod]={name:base64.b64encode(data).decode() for name,data in rgba.items()}
 stats[lod]={}
 for name,data in rgba.items():png(out/f'skull-{lod}-{name}.png',data);stats[lod][name]={'sha256':hashlib.sha256(data).hexdigest(),'uniqueRGBA':len({bytes(data[i:i+4]) for i in range(0,len(data),4)})}
bpy.ops.wm.save_as_mainfile(filepath=str(out/'skull-surface-authoring.blend'))
sha=hashlib.sha256((root/'src/visual/creatures/v2/skull-authored-geometry.ts').read_bytes()).hexdigest()
text="// Generated by scripts/art/bake-skull-surface.py; original UV ivory material bake.\nimport * as THREE from 'three';\nimport { registerSharedCreatureTexture } from './SurfaceDetail';\nexport const skullBakeSourceGeometrySHA256='"+sha+"';\nconst encoded="+json.dumps(encoded,separators=(',',':'))+";\n"
text+='''type Lod='mob'|'boss';type Maps={color:THREE.DataTexture;normal:THREE.DataTexture;orm:THREE.DataTexture};const cache:Partial<Record<Lod,Maps>>={};
export function skullBakedMaps(lod:Lod):Maps {if(cache[lod])return cache[lod]!;const make=(key:keyof Maps)=>{const raw=atob(encoded[lod][key]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const map=new THREE.DataTexture(bytes,256,256,THREE.RGBAFormat);map.name='skull-authored-'+lod+'-'+key;map.colorSpace=key==='color'?THREE.SRGBColorSpace:THREE.NoColorSpace;map.wrapS=map.wrapT=THREE.ClampToEdgeWrapping;map.magFilter=THREE.LinearFilter;map.minFilter=THREE.LinearMipmapLinearFilter;map.generateMipmaps=true;map.flipY=false;map.needsUpdate=true;map.addEventListener('dispose',()=>{if(cache[lod]?.[key]===map)delete cache[lod];});return registerSharedCreatureTexture(map);};const maps={color:make('color'),normal:make('normal'),orm:make('orm')};cache[lod]=maps;return maps;}
export function createSkullBakedMaterial(lod:Lod,cavity=false):THREE.MeshStandardMaterial{const m=skullBakedMaps(lod);const mat=new THREE.MeshStandardMaterial({color:cavity?0x756653:0xffffff,map:m.color,normalMap:m.normal,roughnessMap:m.orm,metalnessMap:m.orm,aoMap:m.orm,roughness:1,metalness:0,aoMapIntensity:.7});mat.normalScale.setScalar(.5);mat.name='authored-ivory-'+lod+(cavity?'-cavity':'');mat.userData.sharedImmutableMaps=true;return mat;}
'''
(root/'src/visual/creatures/v2/skull-baked-surfaces.ts').write_text(text)
manifest={'sourceGeometryModuleSHA256':sha,'size':N,'rawRGBABytes':N*N*4*6,'mipEstimateBytes':N*N*4*8,'maps':stats};(out/'skull-surface-manifest.json').write_text(json.dumps(manifest,indent=2));print('BAKED_SKULL_SURFACE',manifest)
